#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Prove checkpoint-fast-exit reachability in the real BREAK live-crossfade path.

Compare the exact R22 parent and R23 production breaks.c blobs on the same
pinned source dependencies and R22 live-key workload. Add only ephemeral host
counters to compiled copies; never modify either original source tree.
"""
import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

import run_breaks_dual_voice_decoder_compare as r22

BEFORE = '9e1e607e2ddc3028383bfb6ebc85fbc7ac6864c5'
AFTER = '01e0e759d2b8be3b028e0e25d4f93348a36aeb46'
RUNNER_R22 = '4a285e80482c266abc4ac818b4b0ff0910a4930c'
CODE = 'firmware/src/dsp/breaks.c'
FIXTURE = 'tests/host/breaks_reverse_fast_advance_test.c'
ALIGNED = '''    if (i == p) {
        v->seek_pos = UINT32_MAX;
        return;
    }'''
ADD_COUNTER = '''    if (i == p) {
        ++r24_aligned_hits;
        v->seek_pos = UINT32_MAX;
        return;
    }'''


def checked(root, path, expected):
    data = (root / path).read_bytes()
    if r22.blob(data) != expected:
        raise ValueError(f'wrong source blob: {root}/{path}: {r22.blob(data)} expected {expected}')
    return data


def replace_one(s, a, b):
    if s.count(a) != 1:
        raise ValueError('source fixture lacks unique expected anchor: ' + a[:65])
    return s.replace(a, b, 1)


def run(argv, logfile, timeout=180):
    p = subprocess.run(argv, capture_output=True, text=True, timeout=timeout, check=False)
    logfile.write_text('$ ' + ' '.join(map(str, argv)) + '\nexit=' + str(p.returncode) +
                       '\nSTDOUT:\n' + p.stdout + '\nSTDERR:\n' + p.stderr)
    return p


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--before-root', required=True, type=Path)
    ap.add_argument('--after-root', required=True, type=Path)
    ap.add_argument('--output-dir', required=True, type=Path)
    a = ap.parse_args()
    if a.output_dir.exists():
        ap.error('refusing to overwrite an existing evidence directory')
    roots = {'before': a.before_root.resolve(), 'after': a.after_root.resolve()}
    pins = {**r22.COMMON, **r22.RENDERERS['pr93'], FIXTURE: r22.TEST_BLOB}
    checked(roots['before'], CODE, BEFORE)
    checked(roots['after'], CODE, AFTER)
    checked(roots['before'], FIXTURE, r22.TEST_BLOB)
    for kind in roots:
        for path, expected in pins.items():
            if path != CODE:
                checked(roots[kind], path, expected)
    if r22.blob(Path(r22.__file__).read_bytes()) != RUNNER_R22:
        raise ValueError('R22 reference helper changed')
    a.output_dir.mkdir(parents=True, exist_ok=False)
    observations = {}
    with tempfile.TemporaryDirectory(prefix='x0x-aligned-live-') as t:
        temp = Path(t)
        for kind, root in roots.items():
            dst = temp / kind
            for path in pins:
                dest = dst / path
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(root / path, dest)
            code = (dst / CODE).read_text()
            if kind == 'after':
                code = replace_one(code, ALIGNED, ADD_COUNTER)
                code = replace_one(code, 'static void bank_seek_reverse(',
                                   'extern volatile uint64_t r24_aligned_hits;\nstatic void bank_seek_reverse(')
                (dst / CODE).write_text(code)
            fixture = (dst / FIXTURE).read_text()
            fixture = replace_one(fixture, r22.ORIGINAL_RATES, r22.MUSICAL_RATES)
            fixture = replace_one(fixture, r22.ORIGINAL_SIZES, r22.LONG_SIZES)
            fixture = r22.live_crossfade_fixture(fixture)
            fixture = replace_one(fixture, 'volatile uint64_t x0x_host_ima_decode_calls = 0;',
                                  'volatile uint64_t x0x_host_ima_decode_calls = 0;\nvolatile uint64_t r24_aligned_hits = 0;')
            fixture = replace_one(fixture, '    x0x_host_ima_decode_calls=0;',
                                  '    x0x_host_ima_decode_calls=0;\n    r24_aligned_hits=0;')
            fixture = replace_one(fixture, ' overlap=%" PRIu64 " stopped=1\\n",',
                                  ' overlap=%" PRIu64 " aligned=%" PRIu64 " stopped=1\\n",')
            fixture = replace_one(fixture, 'hash,audible,overlap);',
                                  'hash,audible,overlap,r24_aligned_hits);')
            (dst / FIXTURE).write_text(fixture)
            hdr = dst / 'firmware/src/dsp/ima_adpcm.h'
            orig = hdr.read_text()
            if orig.count(r22.FUNC) != 1 or orig.count('#include <stdint.h>') != 1:
                raise ValueError('IMA decoder instrumentation anchor mismatch')
            hdr.write_text(orig.replace('#include <stdint.h>',
                         '#include <stdint.h>\nextern volatile uint64_t x0x_host_ima_decode_calls;')
                         .replace(r22.FUNC, r22.FUNC + '\n    ++x0x_host_ima_decode_calls;'))
            for compiler in ('gcc', 'clang'):
                tag = f'{compiler}-{kind}'
                exe = dst / tag
                cmd = [compiler,'-std=c11','-O2','-Wall','-Wextra','-Werror','-pedantic',
                       '-ffp-contract=off','-I'+str(dst),str(dst/FIXTURE),str(dst/CODE),
                       '-lm','-o',str(exe)]
                p = run(cmd, a.output_dir / (tag+'.compile.log'))
                if p.returncode:
                    raise RuntimeError(f'{tag} compiler failed: {p.returncode}: {p.stderr[:500]}')
                trace = a.output_dir / (tag+'.pcm')
                p = run([str(exe),'--check','--trace',str(trace)], a.output_dir / (tag+'.run.log'))
                if p.returncode:
                    raise RuntimeError(f'{tag} render failed: {p.returncode}: {p.stderr[:500]}')
                neg = run([str(exe)], a.output_dir / (tag+'.negative.log'))
                if neg.returncode != 2:
                    raise RuntimeError(f'{tag} expected invalid invocation exit 2, got {neg.returncode}')
                if trace.stat().st_size != 48*80*64*4:
                    raise RuntimeError(f'{tag} incorrect PCM length')
                rows = {}
                for line in p.stdout.splitlines():
                    parts = dict(kv.split('=',1) for kv in line.split())
                    key = tuple(parts[k] for k in ('n','direction','rate','trial'))
                    if key in rows or not all(k in parts for k in ('aligned','overlap','pcm','stopped')):
                        raise RuntimeError(f'{tag} missing/duplicate coverage event')
                    rows[key] = parts
                if len(rows) != 48:
                    raise RuntimeError(f'{tag} expected 48 real-path cases, got {len(rows)}')
                observations[tag] = {'pcm_sha256': hashlib.sha256(trace.read_bytes()).hexdigest(),
                                     'cases': rows, 'negative_exit': neg.returncode}
                trace.unlink()
    summary = {}
    for compiler in ('gcc','clang'):
        before = observations[compiler+'-before']
        after = observations[compiler+'-after']
        if before['pcm_sha256'] != after['pcm_sha256']:
            raise RuntimeError(f'{compiler} changed observable PCM')
        hits = 0
        by_case = {}
        for key, old in before['cases'].items():
            new = after['cases'].get(key)
            if not new:
                raise RuntimeError(f'{compiler} missing case {key}')
            for field in ('pcm','audible','overlap','decodes','setup','stopped','max','p95','p99'):
                if old[field] != new[field]:
                    raise RuntimeError(f'{compiler} changed {field} in real callback case {key}')
            n = int(new['aligned'])
            if int(old['aligned']) != 0:
                raise RuntimeError(f'{compiler} R22 unexpectedly has new branch')
            if key[1] == 'F' and n:
                raise RuntimeError(f'{compiler} forward playback used reverse fast exit')
            hits += n
            by_case['/'.join(key)] = n
        if hits == 0 or not any(v>0 and '/R/' in k and k.endswith('/1') for k,v in by_case.items()):
            raise RuntimeError(f'{compiler} R23 fast exit not reached during reverse live-pad overlap')
        summary[compiler] = {'real_path_aligned_exit_hits':hits,'pcm_sha256':after['pcm_sha256'],
                             'cases':len(after['cases']), 'reverse_live_overlap_cases_with_hits':
                             sum(v>0 and '/R/' in k and k.endswith('/1') for k,v in by_case.items()),
                             'per_case_hits':by_case}
    if summary['gcc']['pcm_sha256'] != summary['clang']['pcm_sha256']:
        raise RuntimeError('compiler PCM differs')
    report = {'scope':'producer host-only test-only counters on copied source; NOT independent QA or MCU timing',
              'before_breaks_blob':BEFORE,'after_breaks_blob':AFTER,'source_pins':pins,
              'r22_runner_blob':RUNNER_R22,'results':summary,
              'not_run':['Elite/Pro/controller build','independent QA','target timing/XRUN','device','installer'],
              'inherited_failure':'Original fastmath.h:57 UBSan negative shift; PR28 owns'}
    (a.output_dir/'result.json').write_text(json.dumps(report,indent=2,sort_keys=True)+'\n')
    print('PASS: true R23 aligned-checkpoint fast exits observed in live two-voice reverse playback')
    for compiler, x in summary.items():
        print(compiler,x['real_path_aligned_exit_hits'],x['reverse_live_overlap_cases_with_hits'],x['pcm_sha256'])


if __name__ == '__main__':
    try:
        main()
    except (OSError, ValueError, AssertionError, RuntimeError, subprocess.TimeoutExpired) as ex:
        print('FAIL:',ex,file=sys.stderr)
        sys.exit(1)

/* SPDX-License-Identifier: GPL-3.0-only */
/* Undo and redo by difference.
 *
 * The undoable state is one region of bytes (the project after its settings). A shadow copy holds
 * it as it was at the last commit; a commit (the end of a gesture: ui.c decides when) compares the
 * two and stores the runs of bytes that changed, as one entry, with their previous contents. Undo
 * swaps an entry's bytes with the region's, so the entry then holds what undo took away, and redo
 * swaps them back: one copy serves both directions. Every edit is undoable without any code at the
 * place that makes it.
 *
 * Entries live in a byte pool, oldest first; a new one drops the oldest until it fits, and drops
 * whatever was undone and not redone. An entry bigger than the whole pool cannot be kept: the
 * history is emptied (undo_commit says so).
 *
 * Entry: u16 run count, u16 first changed offset, u16 last, u16 pad, then per run u16 offset,
 * u16 length and its bytes, padded to 2. */
#include <stdint.h>

#ifndef UNDO_POOL
/* 4 KiB history: tip after #606 links WBL1 with only ~868 B above the 8 KiB pool floor. */
#define UNDO_POOL 4096u
#endif
#define UNDO_MAX 32
#define UNDO_GAP 8u                    /* unchanged bytes between changes cheaper to keep than a new run */

typedef struct {
    uint8_t *region, *shadow;
    uint32_t len;
    uint8_t pool[UNDO_POOL];
    uint32_t used;
    uint32_t at[UNDO_MAX + 1];         /* entry k starts at pool[at[k]]; at[n] == used */
    int n, cur;                        /* entries kept; how many of them are applied */
} undo_t;

static uint16_t ud_get16(const uint8_t *p) { return (uint16_t)(p[0] | p[1] << 8); }
static void ud_put16(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)(v >> 8);
}

/* shadow must have room for len bytes; the region as it is now is the starting point */
static void undo_init(undo_t *u, void *region, void *shadow, uint32_t len)
{
    uint32_t i;
    u->region = region;
    u->shadow = shadow;
    u->len = len;
    for (i = 0; i < len; i++)
        u->shadow[i] = u->region[i];
    u->used = 0;
    u->n = u->cur = 0;
    u->at[0] = 0;
}

/* forget the history and take the region as it is (a load, a factory reset kept as is) */
static void undo_reset(undo_t *u) { undo_init(u, u->region, u->shadow, u->len); }

static void ud_drop_oldest(undo_t *u)
{
    uint32_t sz = u->at[1], i;
    int k;
    for (i = sz; i < u->used; i++)
        u->pool[i - sz] = u->pool[i];
    u->used -= sz;
    for (k = 0; k < u->n; k++)
        u->at[k] = u->at[k + 1] - sz;
    u->n--;
    u->cur--;
}

/* the changes since the last commit, as one entry. 1 = an entry was made, 0 = nothing changed,
 * -1 = too big to keep (the history is emptied; the region is the new starting point) */
static int undo_commit(undo_t *u)
{
    uint32_t i = 0, sz = 8, runs = 0, lo = 0, hi = 0;
    uint32_t written_runs = 0;
    uint8_t *e;
    /* first pass: the runs and the entry's size */
    while (i < u->len) {
        uint32_t s, end, q;
        if (u->region[i] == u->shadow[i]) {
            i++;
            continue;
        }
        s = end = i;
        while (end + 1u < u->len) {                       /* extend over short gaps */
            uint32_t nxt = end + 1u, lim = end + 1u + UNDO_GAP, found = 0;
            for (q = nxt; q < u->len && q < lim; q++)
                if (u->region[q] != u->shadow[q]) {
                    found = q;
                    break;
                }
            if (!found)
                break;
            end = found;
        }
        if (!runs)
            lo = s;
        hi = end;
        runs++;
        sz += 4u + ((end - s + 1u + 1u) & ~1u);
        i = end + 1u;
    }
    if (!runs)
        return 0;
    u->n = u->cur;                                        /* what was undone is gone */
    u->used = u->at[u->n];
    if (sz > UNDO_POOL) {
        undo_reset(u);
        return -1;
    }
    while (u->n > 0 && (u->n >= UNDO_MAX || u->used + sz > UNDO_POOL))
        ud_drop_oldest(u);
    e = u->pool + u->used;
    ud_put16(e, runs);
    ud_put16(e + 2, lo);
    ud_put16(e + 4, hi);
    ud_put16(e + 6, 0);
    e += 8;
    /* second pass, the same runs: the previous bytes into the entry, the shadow brought up to date */
    i = lo;
    while (i <= hi) {
        uint32_t s, end, q, k;
        if (u->region[i] == u->shadow[i]) {
            i++;
            continue;
        }
        s = end = i;
        while (end + 1u < u->len) {
            uint32_t nxt = end + 1u, lim = end + 1u + UNDO_GAP, found = 0;
            for (q = nxt; q < u->len && q < lim; q++)
                if (u->region[q] != u->shadow[q]) {
                    found = q;
                    break;
                }
            if (!found)
                break;
            end = found;
        }
        /* A concurrent project writer could change the run shape after the
         * sizing pass. Never write beyond the reserved entry in that case. */
        uint32_t n = end - s + 1u;
        if ((uint32_t)(e - (u->pool + u->used)) + 4u + ((n + 1u) & ~1u) > sz) {
            undo_reset(u);
            return -1;
        }
        ud_put16(e, s);
        ud_put16(e + 2, n);
        e += 4;
        for (k = s; k <= end; k++) {
            *e++ = u->shadow[k];
            u->shadow[k] = u->region[k];
        }
        if ((end - s + 1u) & 1u)
            *e++ = 0;
        written_runs++;
        i = end + 1u;
    }
    if (written_runs != runs || (uint32_t)(e - (u->pool + u->used)) != sz) {
        undo_reset(u);
        return -1;
    }
    u->used += sz;
    u->n++;
    u->cur = u->n;
    u->at[u->n] = u->used;
    return 1;
}

/* swap entry k with the region; changed(off, len) for every run, after the swap */
static void ud_swap(undo_t *u, int k, void (*changed)(uint32_t off, uint32_t len))
{
    uint8_t *e = u->pool + u->at[k];
    uint32_t runs = ud_get16(e), r;
    e += 8;
    for (r = 0; r < runs; r++) {
        uint32_t off = ud_get16(e), n = ud_get16(e + 2), j;
        e += 4;
        for (j = 0; j < n; j++) {
            uint8_t t = u->region[off + j];
            u->region[off + j] = e[j];
            u->shadow[off + j] = e[j];
            e[j] = t;
        }
        e += (n + 1u) & ~1u;
        if (changed)
            changed(off, n);
    }
}

/* the span an entry touches (for naming it) */
static void undo_span(const undo_t *u, int k, uint32_t *lo, uint32_t *hi)
{
    *lo = ud_get16(u->pool + u->at[k] + 2);
    *hi = ud_get16(u->pool + u->at[k] + 4);
}

/* 1 = done (lo / hi: what it touched), 0 = nothing to undo / redo. Commit first: an edit that has
 * not been committed yet is not in the history. */
static int undo_undo(undo_t *u, void (*changed)(uint32_t, uint32_t), uint32_t *lo, uint32_t *hi)
{
    if (u->cur == 0)
        return 0;
    u->cur--;
    undo_span(u, u->cur, lo, hi);
    ud_swap(u, u->cur, changed);
    return 1;
}

static int undo_redo(undo_t *u, void (*changed)(uint32_t, uint32_t), uint32_t *lo, uint32_t *hi)
{
    if (u->cur >= u->n)
        return 0;
    undo_span(u, u->cur, lo, hi);
    ud_swap(u, u->cur, changed);
    u->cur++;
    return 1;
}

/* Read the bytes an entry would restore without changing history or its baseline. */
static inline void undo_peek(const undo_t *u,int k,uint32_t off,uint8_t *out,uint32_t len)
{
    for(uint32_t i=0;i<len;i++)out[i]=u->region[off+i];
    const uint8_t *e=u->pool+u->at[k];unsigned runs=ud_get16(e);e+=8;
    for(unsigned r=0;r<runs;r++) {
        uint32_t at=ud_get16(e),n=ud_get16(e+2);e+=4;
        for(uint32_t i=0;i<n;i++)if(at+i>=off && at+i<off+len)out[at+i-off]=e[i];
        e+=(n+1u)&~1u;
    }
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X on the host: the whole app — UI, project, engine, sequencer, every DSP part — run
 * against a simulated FM-1 driven by a script. Audio goes to a WAV, the screen to PNGs,
 * the key / button lights to a text dump, MIDI out to a log. The device-only parts
 * (HAL, USB, OTA, flash driver) are replaced by plat.h implemented here.
 *
 *   x0x_host SCRIPT [OUTDIR]
 *
 * Script, one command per line (# comments):
 *   wait MS                      run the device for MS milliseconds
 *   press BTN | release BTN | tap BTN     (BTN: FX SEL ENV LFO EDIT GLO HOME SAVE ARP SEQ PLAY REC OCT- OCT+)
 *   key K down|up | tapkey K     (K: 0..26 = F3..G5, or w0..w15 white keys, b0..b10 black keys)
 *   turn ENC N [MS]              (ENC: SELECT ALGO PRESET K1 K2 K3 K4; N detents, signed, MS apart, 80 = slow)
 *   spin ENC N                   N detents at once (1 ms), exactly N (no knob acceleration)
 *   arrow L|R down|up|tap        the SMK-37 "<" (L) or ">" (R), as smk_arrows (smk_arrows.h) after each frame
 *   clipmode 0|1                 the clip mode flag for the arrow route only
 *   master N                     MASTER pot 0..4096
 *   param T V I VALUE            a sound pot (engine.h target, voice, index), as its knob would
 *   slot K NAME A.wav [B.wav..]  user sample slot K (0..1): one loop (zone) per WAV, encoded here
 *   slotimg K F.hdr F.bin       slot K from tools/upload_breaks.py --dry-run's image (the device format)
 *   midi B0 B1 B2                incoming USB MIDI message (hex bytes)
 *   wav FILE | wavstop           start / stop recording the output
 *   load N                       the overload guard sees every block cost N% (-1: as measured)
 *                                (start value: env X0X_HOST_LOAD, else -1; tests/run_tests.sh sets 0)
 *   peakreset                    restart the output peak (expect peak_db_min / peak_db_max)
 *   shot FILE.png                save the screen
 *   leds                         print the lit buttons and keys
 *   expect WHAT VALUE            check state (playing, pattern, cue, view-part, ...): exit 1 on mismatch;
 *                                VALUE "<N" / ">N" is a bound
 *   reboot                       save nothing; re-run boot from the simulated flash (persistence test)
 *   snapline B                   remember 303 B's line on the pattern shown (expect linechgB: 1 = it changed since)
 *   storepoke OBJ OFF VAL        write byte VAL (hex) at OFF of the saved object OBJ (0 = the settings; an older save)
 *   storefail 0|1                make simulated flash writes fail or work
 *   projimg FILE                 a project as the FM-1 holds it in RAM (fm1_debug peek of proj): saved
 *                                to the simulated flash and booted, as if it had been made here
 */
#define X0X_HOST 1
#define _POSIX_C_SOURCE 200809L                 /* clock_gettime, CLOCK_MONOTONIC (glibc <time.h>) */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#ifdef __APPLE__
#include <libproc.h>
#include <unistd.h>
#endif
#define __attribute__(x)

/* ------------------------------------------------------------ screen --- */
static uint16_t fb[240 * 240];          /* RGB565, byte-swapped as the panel takes it (gfx.c) */
static void lcd_sync(void) {}
static void lcd_fill(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t c)
{
    uint32_t i, j;
    uint16_t sc = (uint16_t)(((c >> 8) & 0xFFu) | ((c & 0xFFu) << 8));
    for (j = y; j < y + h && j < 240u; j++)
        for (i = x; i < x + w && i < 240u; i++)
            fb[j * 240u + i] = sc;
}
static uint32_t blits;
static void lcd_blit(uint32_t x, uint32_t y, uint32_t w, uint32_t h, const uint16_t *px)
{
    uint32_t i, j;
    blits++;
    for (j = 0; j < h; j++)
        for (i = 0; i < w; i++)
            if (x + i < 240u && y + j < 240u)
                fb[(y + j) * 240u + x + i] = px[j * w + i];
}
#include "../firmware/src/gfx.c"

/* ---------------------------------------------------------- platform --- */
#include "../firmware/src/app/plat.h"

static uint32_t now_ms, held_btn, held_keys, master = 2048;
static int32_t enc_acc[NE];
static uint32_t lit_btn, lit_keys, dim_keys;

uint32_t plat_ms(void) { return now_ms; }
uint32_t plat_buttons(void) { return held_btn; }
static uint8_t key_velocity[NKEYS];
uint32_t plat_keys(void) { return held_keys; }
uint8_t plat_key_velocity(int key)
{
    return (unsigned)key < NKEYS && key_velocity[key] ? key_velocity[key] : 100;
}
int32_t plat_enc(int role)
{
    int32_t v = enc_acc[role];
    enc_acc[role] = 0;
    return v;
}
uint32_t plat_master(void) { return master; }
int plat_battery(void) { return 3; }    /* the simulator: a full battery */
void plat_leds(uint32_t b, uint32_t k)
{
    lit_btn = b;
    lit_keys = k;
}
static int glow_on = 1;                 /* the device's button glow (plat_glow); the lights printed are the bright ones */
void plat_glow(int on) { glow_on = on; }
void plat_play_red(int red) { (void)red; }
void plat_keys_dim(uint32_t k) { dim_keys = k; }      /* dim keys: "o" in the leds print */      /* the device's PLAY colour: green, red while recording */

#define MQ 256
static uint32_t min_q[MQ], mi_w, mi_r;
int engine_midi_held(void);              /* engine.c (X0X_HOST): the notes held from MIDI in */
static FILE *midi_log;
uint32_t plat_midi_mark(void)
{
    __asm__ volatile("" ::: "memory");
    return mi_w;
}
int plat_midi_passed(uint32_t mark)
{
    __asm__ volatile("" ::: "memory");
    return (int32_t)(mi_r-mark)>=0;
}
int plat_midi_pending(void)
{
    __asm__ volatile("" ::: "memory");
    return mi_r != mi_w;
}
int plat_midi_in(uint32_t *pkt)
{
    if (mi_r == mi_w)
        return 0;
    *pkt = min_q[mi_r++ % MQ];
    return 1;
}
static uint32_t midi_out_count, clock_out_count, note_ons, transport_out_count;
static unsigned host_cpu2_active, midi_pulse_crosscore;
void plat_midi_out(uint32_t pkt)
{
    midi_out_count++;
    if ((((pkt >> 8) & 0xF0) == 0x90) && ((pkt >> 24) & 0x7F))
        note_ons++;                                  /* the notes the sequence sent (expect noteons) */
    if (((pkt >> 8) & 0xFF) >= 0xFA && ((pkt >> 8) & 0xFF) <= 0xFC)
        transport_out_count++;
    if (((pkt >> 8) & 0xFF) == 0xF8)
        clock_out_count++;
    else if (midi_log)
        fprintf(midi_log, "%u ms: %02X %02X %02X\n", now_ms, (pkt >> 8) & 0xFF, (pkt >> 16) & 0xFF, (pkt >> 24) & 0xFF);
}

int plat_midi_pulse(uint8_t ch, uint8_t note, uint8_t velocity)
{
    if (host_cpu2_active) midi_pulse_crosscore++;
    plat_midi_out(9u | ((uint32_t)(0x90u | ch) << 8) | ((uint32_t)note << 16) | ((uint32_t)velocity << 24));
    plat_midi_out(8u | ((uint32_t)(0x80u | ch) << 8) | ((uint32_t)note << 16));
    return 1;
}

/* flash: one buffer per object, kept across a simulated reboot */
static uint8_t store[OBJ_NOBJ][PLAT_STORE_MAX];
static int store_len[OBJ_NOBJ] = {-1, -1, -1, -1, -1, -1, -1};
static uint32_t store_writes;
static int store_fail;
int plat_store_load(uint32_t obj, void *dst, uint32_t max)
{
    int n = store_len[obj];
    if (obj >= OBJ_NOBJ || n < 0)
        return -1;
    if ((uint32_t)n > max)
        n = (int)max;
    memcpy(dst, store[obj], (size_t)n);
    return n;
}
int plat_store_save(uint32_t obj, const void *src, uint32_t len)
{
    if (store_fail || obj >= OBJ_NOBJ || len > PLAT_STORE_MAX)
        return -1;
    memcpy(store[obj], src, len);
    store_len[obj] = (int)len;
    store_writes++;
    return 0;
}

/* sample slots, two ways in:
 *  - slotimg: a slot image exactly as tools/upload_breaks.py writes it, read by the firmware's own
 *    slots.c (the device path: what the upload tool writes is what the firmware parses);
 *  - slot: WAVs encoded here, one zone each (quick, for scenarios that do not test the format). */
static uint8_t slot_img[PLAT_NSLOTS][0x1E000];    /* the largest slot (SMK-37 slot 2: 120 KiB) */
static int slot_is_img[PLAT_NSLOTS];
#define SMP_USER_XIP(k) ((const uint8_t *)slot_img[k])
static uint32_t st_crc32(const void *p, uint32_t n)
{
    const uint8_t *b = p;
    uint32_t c = 0xFFFFFFFFu, k;
    while (n--) {
        c ^= *b++;
        for (k = 0; k < 8; k++)
            c = c & 1 ? 0xEDB88320u ^ (c >> 1) : c >> 1;
    }
    return ~c;
}
#include "../firmware/src/app/slots.c"

/* WAV slots */
static uint8_t *slot_data[PLAT_NSLOTS][PLAT_SLOT_ZONES];
static uint32_t slot_n[PLAT_NSLOTS][PLAT_SLOT_ZONES], slot_rate[PLAT_NSLOTS][PLAT_SLOT_ZONES];
static int slot_nz[PLAT_NSLOTS];
static char slot_name[PLAT_NSLOTS][9];
int plat_slot_zones(int k)
{
    if (k < 0 || k >= PLAT_NSLOTS)
        return 0;
    return slot_is_img[k] ? usr_nz[k] : slot_nz[k];
}
const uint8_t *plat_slot(int k, int z, uint32_t *ns, uint32_t *rate, char name[9])
{
    if (k >= 0 && k < PLAT_NSLOTS && slot_is_img[k]) {    /* plat_fm1.c's plat_slot, verbatim */
        const smp_user_hdr_t *h;
        uint32_t i;
        if (z < 0 || z >= usr_nz[k])
            return 0;
        h = (const smp_user_hdr_t *)smp_user_xip((uint32_t)k);
        for (i = 0; i < 8u; i++)
            name[i] = h->name[i] >= 32 && h->name[i] < 127 ? h->name[i] : 0;
        name[8] = 0;
        *ns = h->zone[z].n;
        *rate = (h->zone[z].rate * 44100u + 32768u) >> 16;
        return smp_user_xip((uint32_t)k) + SMP_USER_DATA + h->zone[z].off;
    }
    if (k < 0 || k >= PLAT_NSLOTS || z < 0 || z >= slot_nz[k])
        return 0;
    *ns = slot_n[k][z];
    *rate = slot_rate[k][z];
    memcpy(name, slot_name[k], 9);
    return slot_data[k][z];
}

